import{describe,it,expect}from"vitest";import{CHIEF_JUSTICES_DATA,filterCJIData}from"../../frontend/chief-justices-timeline/script.js";describe("Chief Justices of India Timeline",()=>{it("should contain a complete dataset of Chief Justices across decades",()=>{expect(Array.isArray(CHIEF_JUSTICES_DATA)).toBe(!0),expect(CHIEF_JUSTICES_DATA.length).toBeGreaterThanOrEqual(8),CHIEF_JUSTICES_DATA.forEach(e=>{expect(e).toHaveProperty("id"),expect(e).toHaveProperty("number"),expect(e).toHaveProperty("name"),expect(e).toHaveProperty("tenure"),expect(e).toHaveProperty("appointmentDate"),expect(e).toHaveProperty("retirementDate"),expect(e).toHaveProperty("tenureLength"),expect(e).toHaveProperty("decade"),expect(e).toHaveProperty("domain"),expect(e).toHaveProperty("landmarkJudgments"),expect(Array.isArray(e.landmarkJudgments)).toBe(!0),expect(e.landmarkJudgments.length).toBeGreaterThan(0),expect(e).toHaveProperty("reforms")})}),it("should filter CJI data by search term",()=>{const e=filterCJIData(CHIEF_JUSTICES_DATA,"Kania");expect(e.length).toBe(1),expect(e[0].number).toBe("1st CJI");const t=filterCJIData(CHIEF_JUSTICES_DATA,"Kesavananda");expect(t.length).toBe(1),expect(t[0].name).toBe("S. M. Sikri")}),it("should filter CJI data by decade",()=>{const e=filterCJIData(CHIEF_JUSTICES_DATA,"","1970s","all");expect(e.length).toBeGreaterThan(0),e.forEach(e=>expect(e.decade).toBe("1970s"))}),it("should filter CJI data by focus domain",()=>{const e=filterCJIData(CHIEF_JUSTICES_DATA,"","all","Judicial Activism & PIL");expect(e.length).toBeGreaterThan(0),e.forEach(e=>expect(e.domain).toBe("Judicial Activism & PIL"))})});